excels.excel:

EXPORT WITH SHEET="样式", HEADER=true,
    MAPPING={"a":"姓名","b":"年龄","c":"班级"},
    STYLE={
        ROW 1:{fontName:Arial,fontHeightInPoints:12,bold:true,italic:true,color:yellow,fillPattern:solid_foreground,fillForegroundColor:darkBlue,alignment:center},
        A2:C100:{alignment:center,wrapText:true,borderBottom:thin,fillForegroundColor:lightYellow}
    }
